package net.civeira.phylax.feature.observe.observedembed.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbed;
import net.civeira.phylax.feature.observe.observedembed.domain.valueobject.AllowedOriginsVO;

class AllowedOriginsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of allowed origins of observed embed")
  void test_allowed_origins_value_holder_assign_plain_value() {
    Object holder = new Object();
    AllowedOriginsValueHolder<Object> value = new AllowedOriginsValueHolder<>(holder);
    Assertions.assertSame(holder, value.allowedOrigins("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getAllowedOriginsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getAllowedOrigins().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of allowed origins of observed embed")
  void test_allowed_origins_value_holder_assign_value_object() {
    Object holder = new Object();
    AllowedOriginsValueHolder<Object> value = new AllowedOriginsValueHolder<>(holder);
    AllowedOriginsVO vo = AllowedOriginsVO.from("one");
    Assertions.assertFalse(value.getAllowedOriginsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.allowedOrigins(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAllowedOriginsValue().orElseThrow());
    Assertions.assertSame(holder, value.allowedOrigins(Optional.empty()));
    Assertions.assertFalse(value.getAllowedOriginsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.allowedOrigins(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAllowedOriginsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of allowed origins of observed embed against the original")
  void test_allowed_origins_value_holder_read() {
    Object holder = new Object();
    AllowedOriginsValueHolder<Object> value = new AllowedOriginsValueHolder<>(holder);
    AllowedOriginsVO vo = AllowedOriginsVO.from("one");
    AllowedOriginsVO other = AllowedOriginsVO.from("one");
    ObservedEmbed original = Mockito.mock(ObservedEmbed.class);
    Mockito.when(original.getAllowedOriginsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAllowedOrigins(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readAllowedOrigins(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.allowedOrigins(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAllowedOrigins(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAllowedOrigins(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of allowed origins of observed embed")
  void test_allowed_origins_value_holder_unset() {
    Object holder = new Object();
    AllowedOriginsValueHolder<Object> value = new AllowedOriginsValueHolder<>(holder);
    AllowedOriginsVO vo = AllowedOriginsVO.from("one");
    value.allowedOrigins(vo);
    Assertions.assertSame(holder, value.unsetAllowedOriginsIfMatches("allowedOrigins_other"));
    Assertions.assertTrue(value.getAllowedOriginsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAllowedOriginsIfMatches("allowedOrigins"));
    Assertions.assertFalse(value.getAllowedOriginsValue().isPresent(),
        "The field name must clear the value");
    value.allowedOrigins(vo);
    Assertions.assertSame(holder, value.unsetAllowedOrigins());
    Assertions.assertFalse(value.getAllowedOriginsValue().isPresent(),
        "Unset must clear the value");
  }
}
